/**
 * Symbol identity stable across refs: '<module>:<qualname>#<ordinal>'. Module-level code uses the qualname '<module>'.
 * Constraints: maxLength=1024, pattern="^[^\\s:]+:[^\\s#]+#[0-9]+$"
 */
