/**
 * RFC 3339 UTC timestamp with 'Z' suffix.
 * Constraints: pattern="^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,9})?Z$"
 */
export type Timestamp = string;

/**
 * Duration in milliseconds.
 * Constraints: minimum=0
 */
